import os
import glob
import shutil

def task_func(directory, archive_dir='archive'):
    errors = []

    if not os.path.isdir(directory):
        return False, [f"Source directory does not exist or is not a directory: {directory}"]

    try:
        os.makedirs(archive_dir, exist_ok=True)
    except Exception as exc:
        return False, [f"Failed to create archive directory '{archive_dir}': {exc}"]

    candidates = glob.glob(os.path.join(directory, '*')) + glob.glob(os.path.join(directory, '.*'))
    files = sorted({
        path for path in candidates
        if os.path.isfile(path) and path.lower().endswith('.json')
    })

    for src in files:
        dest = os.path.join(archive_dir, os.path.basename(src))
        try:
            if os.path.abspath(src) == os.path.abspath(dest):
                continue
            if os.path.exists(dest):
                raise FileExistsError(f"Destination file already exists: {dest}")
            shutil.move(src, dest)
        except Exception as exc:
            errors.append(f"Failed to move '{src}' to '{dest}': {exc}")

    return len(errors) == 0, errors
