import numpy as np
import matplotlib.pyplot as plt
from scipy import stats

def task_func(original):
    def _extract_numeric(item):
        numeric_items = []
        if isinstance(item, (list, tuple, np.ndarray)):
            for sub_item in item:
                numeric_items.extend(_extract_numeric(sub_item))
        else:
            if isinstance(item, (int, float, np.integer, np.floating, np.number)) and not isinstance(item, bool):
                numeric_items.append(float(item))
        return numeric_items

    extracted = []
    if original is not None:
        for element in original:
            extracted.extend(_extract_numeric(element))

    values = np.array(extracted, dtype=float)

    if values.size > 0:
        basic_stats = {
            "mean": float(np.mean(values)),
            "std": float(np.std(values)),
            "min": float(np.min(values)),
            "max": float(np.max(values)),
        }
    else:
        basic_stats = {
            "mean": np.nan,
            "std": np.nan,
            "min": np.nan,
            "max": np.nan,
        }

    fig, ax = plt.subplots()

    if values.size > 0:
        ax.hist(values, bins="auto", density=True, alpha=0.6, color="steelblue", edgecolor="black")

        std = basic_stats["std"]
        if np.isfinite(std) and std > 0:
            x_min = float(np.min(values))
            x_max = float(np.max(values))
            padding = 0.1 * (x_max - x_min) if x_max > x_min else std * 4
            if padding <= 0:
                padding = std * 4
            x = np.linspace(x_min - padding, x_max + padding, 400)
            pdf = stats.norm.pdf(x, loc=basic_stats["mean"], scale=std)
            ax.plot(x, pdf, color="crimson", linewidth=2, label="PDF")
            ax.legend()
    else:
        ax.text(0.5, 0.5, "No numeric values found", ha="center", va="center", transform=ax.transAxes)

    ax.set_xlabel("Value")
    ax.set_ylabel("Density")
    ax.set_title("Histogram with Overlaid PDF")

    return values, basic_stats, ax
