import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

def task_func(product_dict, product_keys):
    columns = ['Product', 'Quantity', 'Price', 'Profit', 'Average Price', 'Average Profit']

    if product_dict is None:
        product_dict = {}

    if product_keys is None:
        keys = []
    elif isinstance(product_keys, str):
        keys = [product_keys]
    else:
        keys = list(product_keys)

    records = []

    for key in keys:
        if key not in product_dict:
            continue

        entry = product_dict[key]
        quantity = price = profit = None

        if isinstance(entry, dict):
            for k in ('quantity', 'Quantity'):
                if k in entry:
                    quantity = entry[k]
                    break
            for k in ('price', 'Price'):
                if k in entry:
                    price = entry[k]
                    break
            for k in ('profit', 'Profit'):
                if k in entry:
                    profit = entry[k]
                    break
        elif isinstance(entry, (list, tuple, np.ndarray, pd.Series)):
            if len(entry) >= 3:
                quantity, price, profit = entry[0], entry[1], entry[2]
            else:
                continue
        else:
            continue

        vals = pd.to_numeric(pd.Series([quantity, price, profit]), errors='coerce')
        if vals.isna().any():
            continue

        records.append([key, vals.iloc[0], vals.iloc[1], vals.iloc[2]])

    if not records:
        return pd.DataFrame(columns=columns), None

    df = pd.DataFrame(records, columns=['Product', 'Quantity', 'Price', 'Profit'])
    avg_price = float(np.mean(df['Price'].astype(float)))
    avg_profit = float(np.mean(df['Profit'].astype(float)))

    df['Average Price'] = avg_price
    df['Average Profit'] = avg_profit

    fig, ax = plt.subplots()
    ax.bar(df['Product'], df['Profit'])
    ax.set_title('Profit by Product')
    ax.set_xlabel('Product')
    ax.set_ylabel('Profit')
    if len(df) > 1:
        plt.setp(ax.get_xticklabels(), rotation=45, ha='right')
    fig.tight_layout()

    return df, ax
