import zipfile
import os
import re
import shutil


def task_func(source_dir: str, target_dir: str, archive_name: str = 'archive.zip') -> str:
    """
    Archive all files from source_dir whose filename ends with the '_processed'
    suffix (optionally followed by one or more extensions) into a zip file
    created inside target_dir.

    Returns:
        str: The path to the created archive.
    """
    source_dir = os.path.abspath(source_dir)
    target_dir = os.path.abspath(target_dir)
    os.makedirs(target_dir, exist_ok=True)

    archive_path = os.path.join(target_dir, os.path.basename(archive_name))
    processed_pattern = re.compile(r"_processed(?:\.[^.\\/]+)*$")

    def _is_within(child_path: str, parent_path: str) -> bool:
        try:
            return os.path.commonpath([os.path.abspath(child_path), os.path.abspath(parent_path)]) == os.path.abspath(parent_path)
        except ValueError:
            return False

    files_to_archive = []

    if os.path.isdir(source_dir):
        for root, dirs, files in os.walk(source_dir):
            # Avoid traversing into the target directory if it is inside the source tree.
            dirs[:] = [
                d for d in dirs
                if not _is_within(os.path.join(root, d), target_dir)
            ]

            for filename in files:
                if processed_pattern.search(filename):
                    full_path = os.path.join(root, filename)
                    if os.path.abspath(full_path) != os.path.abspath(archive_path):
                        files_to_archive.append(full_path)

    with zipfile.ZipFile(archive_path, mode='w', compression=zipfile.ZIP_DEFLATED) as zf:
        for file_path in sorted(files_to_archive):
            arcname = os.path.relpath(file_path, source_dir).replace(os.sep, '/')
            zf.write(file_path, arcname)

    return archive_path
