import numpy as np
import matplotlib.pyplot as plt
from scipy import stats

def task_func(original):
    def is_numeric(value):
        return isinstance(value, (int, float, np.integer, np.floating)) and not isinstance(value, bool)

    values = []

    for item in original:
        if isinstance(item, (tuple, list, np.ndarray)):
            for element in item:
                if is_numeric(element):
                    element = float(element)
                    if np.isfinite(element):
                        values.append(element)
        elif is_numeric(item):
            item = float(item)
            if np.isfinite(item):
                values.append(item)

    arr = np.asarray(values, dtype=float)

    if arr.size > 0:
        mean = float(np.mean(arr))
        std = float(np.std(arr))
        min_val = float(np.min(arr))
        max_val = float(np.max(arr))
    else:
        mean = std = min_val = max_val = np.nan

    stats_dict = {
        "mean": mean,
        "std": std,
        "min": min_val,
        "max": max_val,
    }

    fig, ax = plt.subplots()

    if arr.size > 0:
        hist_range = None
        if min_val == max_val:
            pad = 1.0 if min_val == 0 else abs(min_val) * 0.1
            if pad == 0:
                pad = 1.0
            hist_range = (min_val - pad, max_val + pad)

        ax.hist(arr, density=True, alpha=0.6, bins="auto", range=hist_range)

        if np.isfinite(std) and std > 0:
            x_min, x_max = min_val, max_val
            if x_min == x_max:
                pad = 1.0 if x_min == 0 else abs(x_min) * 0.1
                if pad == 0:
                    pad = 1.0
                x_min -= pad
                x_max += pad
            x = np.linspace(x_min, x_max, 200)
            pdf = stats.norm.pdf(x, loc=mean, scale=std)
            ax.plot(x, pdf, linewidth=2)
        else:
            ax.axvline(mean, linewidth=2)
    else:
        ax.text(
            0.5,
            0.5,
            "No numeric data found",
            ha="center",
            va="center",
            transform=ax.transAxes,
        )

    ax.set_xlabel("Value")
    ax.set_ylabel("Density")
    ax.set_title("Histogram with Overlaid PDF")

    return arr, stats_dict, ax
