    # Validate that the target column is numeric-convertible.
    try:
        selected_values = pd.to_numeric(df[selected_col], errors="raise")
    except Exception:
        raise KeyError(column) from None

    # Validate non-negativity for fitness metric columns if present.
    for metric in ("steps", "calories burned", "distance walked"):
        if metric in normalized_columns:
