import re
from nltk import word_tokenize
from collections import Counter

def task_func(input_str):
    if input_str is None:
        return {}

    text = str(input_str).lower()

    # Extract word-like tokens using regex, removing punctuation, special characters, and spaces.
    words = re.findall(r"[^\W_]+", text, flags=re.UNICODE)

    if not words:
        return {}

    # Use NLTK tokenizer if available; fall back to regex tokens otherwise.
    try:
        tokenized = word_tokenize(" ".join(words))
        words = [token for token in tokenized if re.fullmatch(r"[^\W_]+", token, flags=re.UNICODE)]
    except Exception:
        pass

    return dict(Counter(words))
