import configparser
import os
import shutil

def task_func(config_file_path, archieve_dir='/home/user/archive'):
    config_file_path = os.path.abspath(os.path.expanduser(config_file_path))
    if not os.path.isfile(config_file_path):
        raise FileNotFoundError(f"Configuration file not found: {config_file_path}")

    config = configparser.ConfigParser()
    try:
        read_files = config.read(config_file_path)
        if not read_files:
            raise Exception("Failed to read configuration file.")

        if not config.has_section("Project") or not config.has_option("Project", "directory"):
            raise Exception("Missing [Project] section or directory option in configuration file.")

        project_dir = os.path.abspath(os.path.expanduser(config.get("Project", "directory").strip()))
        if not os.path.isdir(project_dir):
            raise FileNotFoundError(f"Project directory not found: {project_dir}")

        archieve_dir = os.path.abspath(os.path.expanduser(archieve_dir))
        if os.path.exists(archieve_dir):
            if not os.path.isdir(archieve_dir):
                raise Exception(f"Archive path exists and is not a directory: {archieve_dir}")
        else:
            os.makedirs(archieve_dir, exist_ok=True)

        project_basename = os.path.basename(os.path.normpath(project_dir))
        archive_base = os.path.join(archieve_dir, project_basename)

        archive_path = shutil.make_archive(
            base_name=archive_base,
            format="zip",
            root_dir=os.path.dirname(os.path.normpath(project_dir)),
            base_dir=project_basename,
        )

        if not os.path.isfile(archive_path):
            raise Exception("ZIP archive could not be created.")

        return True

    except FileNotFoundError:
        raise
    except Exception as exc:
        raise Exception(f"ZIP archive could not be created: {exc}") from exc
