import os
import glob
import shutil


def task_func(directory, archive_dir='archive'):
    errors = []

    try:
        source_dir = os.path.abspath(directory)
    except Exception as exc:
        return False, [f"Invalid source directory {directory!r}: {exc}"]

    try:
        archive_path = os.path.abspath(archive_dir)
    except Exception as exc:
        return False, [f"Invalid archive directory {archive_dir!r}: {exc}"]

    if not os.path.exists(source_dir):
        return False, [f"Source directory does not exist: {source_dir}"]

    if not os.path.isdir(source_dir):
        return False, [f"Source path is not a directory: {source_dir}"]

    if source_dir == archive_path:
        return False, ["Archive directory must be different from source directory."]

    try:
        os.makedirs(archive_path, exist_ok=True)
    except Exception as exc:
        return False, [f"Failed to create archive directory {archive_path}: {exc}"]

    json_files = [
        path
        for path in glob.glob(os.path.join(source_dir, "*"))
        if os.path.isfile(path) and path.lower().endswith(".json")
    ]

    for src in sorted(json_files):
        dst = os.path.join(archive_path, os.path.basename(src))
        try:
            if os.path.exists(dst):
                raise FileExistsError(f"Destination file already exists: {dst}")
            shutil.move(src, dst)
        except Exception as exc:
            errors.append(f"Failed to move {src} -> {dst}: {exc}")

    return len(errors) == 0, errors
